steps.run:
$vsRoot = 'C:\Program Files\Microsoft Visual Studio\2022\Enterprise'
& "$vsRoot\Common7\Tools\Launch-VsDevShell.ps1" -SkipAutomaticLocation -Arch amd64 -HostArch amd64
if (-not $env:VCToolsInstallDir -or -not $env:WindowsSdkDir) { throw 'MSVC developer environment failed' }
$python = 'C:\hostedtoolcache\windows\Python\3.12.10\x64\python.exe'
$cargo = (rustup which --toolchain 1.97.1 cargo).Trim()
if ($LASTEXITCODE -ne 0) { throw 'Pinned Cargo resolution failed' }
$rustc = (rustup which --toolchain 1.97.1 rustc).Trim()
if ($LASTEXITCODE -ne 0) { throw 'Pinned Rustc resolution failed' }
$rustup = (Get-Command rustup).Source
& $python -B tests/native-provider-qualification/installed-native-capability/ci.py --source "$env:GITHUB_WORKSPACE" --output "$env:RUNNER_TEMP/private-installed-capability" --target "$env:RUNNER_TEMP/private-installed-target" --head "$env:CLI_SOURCE_SHA" --run-id "$env:GITHUB_RUN_ID" --run-attempt "$env:GITHUB_RUN_ATTEMPT" --cargo "$cargo" --rustc "$rustc" --rustup "$rustup"
if ($LASTEXITCODE -ne 0) { throw 'Private Windows installation producer failed' }

$python = 'C:\hostedtoolcache\windows\Python\3.12.10\x64\python.exe'
& $python -B tests/native-provider-qualification/installed-native-capability/admission_test.py --root "$env:GITHUB_WORKSPACE" --proof "$env:RUNNER_TEMP/private-installed-capability" --head "$env:CLI_SOURCE_SHA" --platform win32 --run-id "$env:GITHUB_RUN_ID" --run-attempt "$env:GITHUB_RUN_ATTEMPT"
if ($LASTEXITCODE -ne 0) { throw 'Private installation admission controls failed' }
& $python -B tests/native-provider-qualification/installed-native-capability/admission.py --root "$env:GITHUB_WORKSPACE" --proof "$env:RUNNER_TEMP/private-installed-capability" --head "$env:CLI_SOURCE_SHA" --platform win32 --live --run-id "$env:GITHUB_RUN_ID" --run-attempt "$env:GITHUB_RUN_ATTEMPT"
if ($LASTEXITCODE -ne 0) { throw 'Private installation qualification remains incomplete' }
